class Solution {
    public List<String> letterCombinations(String digits) {
        List<String> res = new ArrayList<>();
        if (digits == null || digits.isEmpty()) return res;
        String[] phone = {"", "", "abc", "def", "ghi", "jkl", "mno", "pqrs", "tuv", "wxyz"};
        StringBuilder sb = new StringBuilder();
        dfs(digits, phone, 0, sb, res);
        return res;
    }
    private void dfs(String digits, String[] phone, int idx, StringBuilder sb, List<String> res) {
        if (idx == digits.length()) {
            res.add(sb.toString());
            return;
        }
        String letters = phone[digits.charAt(idx) - '0'];
        for (int i = 0; i < letters.length(); i++) {
            sb.append(letters.charAt(i));
            dfs(digits, phone, idx + 1, sb, res);
            sb.deleteCharAt(sb.length() - 1);
        }
    }
}

var letterCombinations = function(digits) {
    if (!digits) return [];
    const phone = {
        '2': 'abc', '3': 'def', '4': 'ghi', '5': 'jkl',
        '6': 'mno', '7': 'pqrs', '8': 'tuv', '9': 'wxyz'
    };
    const res = [];
    function backtrack(idx, path) {
        if (idx === digits.length) {
            res.push(path.join(''));
            return;
        }
        for (const ch of phone[digits[idx]]) {
            path.push(ch);
            backtrack(idx + 1, path);
            path.pop();
        }
    }
    backtrack(0, []);
    return res;
};
